            errors["supplierId"] = ["supplierId does not reference an existing supplier."];
        return errors;
    }

    private static async Task<IResult?> TrySave(WarehouseDbContext db)
    {
        try
        {
            await db.SaveChangesAsync();
            return null;
        }
        catch (DbUpdateException ex) when (ex.InnerException is SqliteException { SqliteErrorCode: 19 })
        {
            return Results.Problem(statusCode: StatusCodes.Status409Conflict, title: "Conflict",
                detail: "A unique value is already taken or the object is still referenced.");
        }
    }
